// Jobs start in queue order; at most `limit` run at once. Return each job's finish time, in queue order.
function finishTimes(durations: number[], limit: number): number[] {
  return [];
}

console.log(finishTimes([400, 250, 300, 100, 500, 200], 2));

solution:
function finishTimes(durations: number[], limit: number): number[] {
  if (!Number.isInteger(limit) || limit < 1) throw new Error("limit must be a positive integer");
  const free = new Array(Math.min(limit, durations.length)).fill(0);
  return durations.map((ms) => {
    let best = 0;
    for (let s = 1; s < free.length; s++) if (free[s] < free[best]) best = s;
    free[best] += ms;
    return free[best];
  });
}
